// Serper候補をURL単位で重複除去し、検索根拠を保持したまま企業データへ整形
// n8n Task RunnerではグローバルURLが存在しない環境があるため、文字列だけで安全に正規化する。
const p = $('L-01: 検索パラメータ設定').first().json;
const searchResponse = $input.first().json;
if (searchResponse.success === false || searchResponse.error) {
  const detail = searchResponse.error?.message || searchResponse.error || '検索APIが失敗しました';
  throw new Error(typeof detail === 'string' ? detail : JSON.stringify(detail));
}
const items = searchResponse.items || [];
const emptyResult = () => [{ json: { companyName: '', companyUrl: '', projectId: p.projectId || '', runId: p.runId || '', skipItem: true, noCandidates: true }, pairedItem: { item: 0 } }];
if (!items.length) return emptyResult();
const trackingKeys = new Set(['utm_source','utm_medium','utm_campaign','utm_term','utm_content','gclid','fbclid']);
const normalizeUrl = raw => {
  const value = String(raw || '').trim().split('#')[0];
  const match = value.match(/^(https?):\/\/([^/]+)(.*)$/i);
  if (!match) return '';
  const protocol = match[1].toLowerCase();
  const host = match[2].toLowerCase().replace(/^www\./, '');
  const rest = match[3] || '/';
  const question = rest.indexOf('?');
  const rawPath = question >= 0 ? rest.slice(0, question) : rest;
  const rawQuery = question >= 0 ? rest.slice(question + 1) : '';
  const path = rawPath.replace(/\/+$/, '') || '/';
  const query = rawQuery.split('&').filter(Boolean).filter(part => {
    const key = (part.split('=')[0] || '').replace(/\+/g, ' ').toLowerCase();
    return !trackingKeys.has(key);
  });
  return protocol + '://' + host + path + (query.length ? '?' + query.join('&') : '');
};
const seenUrls = new Set();
const output = items.reduce((acc, item) => {
  const link = item.link || '';
  const normalizedUrl = normalizeUrl(link);
  if (!normalizedUrl || seenUrls.has(normalizedUrl)) return acc;
  seenUrls.add(normalizedUrl);
  const title = item.title || '';
  const segments = title.split(/[|–—｜]|-(?=[^-])/).map(s => s.trim()).filter(Boolean);
  const companyName = segments.length > 1 ? segments.reduce((a, b) => a.length >= b.length ? a : b) : title;
  acc.push({ json: {
    ...item,
    companyName, companyUrl: link,
    phone: item.phone || '', address: item.address || '',
    industry: p.industry, area: p.area,
    spreadsheetId: p.spreadsheetId || '', projectId: p.projectId || '', runId: p.runId || '',
    skipItem: false,
  }, pairedItem: { item: 0 } });
  return acc;
}, []);
return output.length ? output : emptyResult();

// L-05: 同一検索内のURL重複は前段で除去済み。
// 保存済みデータとの最終的な重複除去はcomplete APIが担当する。
const items = $input.all();
return items.map(({ json: c }, index) => ({
  json: { ...c, isDuplicate: false },
  pairedItem: { item: index }
}));

// Serper候補と検索根拠をまとめ、欠落確認できる安定ID付きバッチへ分割する
const items = $input.all();
const p = $('L-01: 検索パラメータ設定').first().json;
const keywords = Array.isArray(p.keywords) ? p.keywords : JSON.parse(p.keywords || '[]');
let rawItems = [];
try { rawItems = $('検索結果を分割').all().map(i => i.json); } catch(e) {}
const rawByUrl = new Map(rawItems.filter(r => r.link).map(r => [r.link, r]));
const records = items.map(({ json: c }) => {
  const raw = rawByUrl.get(c.companyUrl) || {};
  return {
    company: c,
    urlItem: {
      url: c.companyUrl || '',
      baseUrl: c.companyUrl || '',
      industry: p.industry || '',
      keywords,
      area: p.area || '',
      searchArea: raw.area || p.area || '',
      source: raw.source || undefined,
      sourceName: c.companyName || raw.title || '',
      sourceTitle: raw.title || c.companyName || '',
      sourceSnippet: raw.snippet || '',
      sourceAddress: raw.address || '',
      sourcePhone: raw.phone || '',
      sourceCategory: raw.category || '',
    },
  };
}).filter(record => record.urlItem.url);

// Keep each request small enough to finish before n8n's HTTP timeout and
// persist progress frequently. Candidate selection itself is unchanged.
const BATCH_SIZE = 40;
const batches = [];
for (let offset = 0; offset < records.length; offset += BATCH_SIZE) {
  const batch = records.slice(offset, offset + BATCH_SIZE);
  const sequence = batches.length + 1;
  batches.push({ json: {
    batchId: `${p.runId || 'run'}:${String(sequence).padStart(4, '0')}`,
    runId: p.runId || '',
    projectId: p.projectId || '',
    urlItems: batch.map(record => record.urlItem),
    companies: batch.map(record => record.company),
  }});
}
if (!batches.length) {
  batches.push({ json: {
    batchId: `${p.runId || 'run'}:0001`,
    runId: p.runId || '',
    projectId: p.projectId || '',
    urlItems: [],
    companies: [],
  }});
}
return batches;

// 全スクレイプAPIバッチの結果を展開
const allInput = $input.all();
if (!allInput.length) return [];
const results = allInput.flatMap(item => item.json.results || []);
if (!results.length) return [{ json: { noAcceptedResults: true } }];

let companies = [];
try {
  companies = $('URL収集').all().flatMap(item => item.json.companies || []);
} catch(e) {}

const companyMap = {};
for (const c of companies) {
  if (c.companyUrl) companyMap[c.companyUrl] = c;
}

return results
  .filter(r => r.url || r.baseUrl)
  .map(r => {
    const origUrl = r.url || r.baseUrl || '';
    const orig = companyMap[origUrl] || {};
    return { json: {
      companyUrl: origUrl,
      companyName: orig.companyName || r.companyName || '',
      keyword: orig.keyword || '',
      formUrl: r.formUrl || null,
      email: r.email || null,
      phone: r.phone || null,
      address: r.address || null,
      hasContactLink: r.hasContactLink || false,
      contactLinks: r.contactLinks || [],
      formPageTitle: r.formPageTitle || '',
      formTypeHint: r.formTypeHint || 'unknown',
      error: r.error || null,
    } };
  });

const p = $('L-01: 検索パラメータ設定').first().json;
function nodeItems(name) {
  try { return $(name).all().map(item => item.json || {}); } catch(e) { return []; }
}
const search = nodeItems('L-02: Serper検索（公式HP候補取得）')[0] || {};
const scrapeItems = nodeItems('L-03: スクレイプAPI');
const urlBatches = nodeItems('URL収集');
const metas = scrapeItems.filter(item => item.success === true && item.meta).map(item => item.meta);
const sum = key => metas.reduce((total, meta) => total + (Number(meta[key]) || 0), 0);

const totalCompanies = Number(search.stats?.candidateCount ?? search.count ?? 0) || 0;
const queuedCandidateCount = urlBatches.reduce(
  (total, batch) => total + (Array.isArray(batch.urlItems) ? batch.urlItems.length : 0),
  0
);
const expectedCandidateCount = Math.max(totalCompanies, queuedCandidateCount);
const preScrapeResolvedCount = Math.max(0, expectedCandidateCount - queuedCandidateCount);
const scrapedProcessedCount = sum('searchedCandidateCount');
const processedCandidateCount = Math.min(
  expectedCandidateCount,
  preScrapeResolvedCount + scrapedProcessedCount
);
const pendingCandidateCount = Math.max(0, expectedCandidateCount - processedCandidateCount);
const batchCount = urlBatches.length;
const completedBatchCount = metas.length;
const failedBatchCount = Math.max(0, batchCount - completedBatchCount);
const resultSetComplete = failedBatchCount === 0 && pendingCandidateCount === 0;

const failedScrapes = scrapeItems.filter(item => item.success !== true || !item.meta);
const errorParts = [];
if (search.error) {
  errorParts.push(typeof search.error === 'string'
    ? search.error
    : search.error.message || JSON.stringify(search.error));
}
if (failedBatchCount > 0) {
  errorParts.push('スクレイプ失敗バッチ: ' + failedBatchCount + '/' + batchCount);
}
if (pendingCandidateCount > 0) {
  errorParts.push('未処理候補: ' + pendingCandidateCount + '/' + expectedCandidateCount);
}
const error = errorParts.join(' / ');

const afterDedup = sum('relevanceAcceptedCount');
const formFoundCount = sum('formFoundCount');
const relevanceReasonCounts = {};
for (const meta of metas) {
  for (const [reason, count] of Object.entries(meta.relevanceReasonCounts || {})) {
    relevanceReasonCounts[reason] = (relevanceReasonCounts[reason] || 0) + (Number(count) || 0);
  }
}

const warningMessages = [];
if (search.warning) warningMessages.push(String(search.warning));
for (const issue of (Array.isArray(search.errors) ? search.errors : [])) {
  warningMessages.push(
    ('Serper ' + (issue.status || '') + ': ' + (issue.text || JSON.stringify(issue))).trim()
  );
}
for (const meta of metas) {
  for (const issue of (Array.isArray(meta.fetchErrorSamples) ? meta.fetchErrorSamples : [])) {
    warningMessages.push('HP取得失敗 ' + (issue.url || '') + ': ' + (issue.error || '不明'));
  }
}
for (const failed of failedScrapes) {
  const detail = failed.error ?? failed.message ?? failed;
  warningMessages.push(
    'スクレイプAPI: ' + (typeof detail === 'string' ? detail : JSON.stringify(detail))
  );
}

const elapsedMs = sum('elapsedMs');
const results = {
  totalCompanies,
  afterDedup,
  successCount: sum('successCount'),
  errorCount: sum('errorCount') + failedBatchCount,
  formFoundCount,
  formFoundRate: Math.round((formFoundCount / Math.max(afterDedup, 1)) * 100),
  elapsedMs,
  avgMsPerItem: Math.round(elapsedMs / Math.max(processedCandidateCount, 1)),
  queryCount: search.stats?.queriesExecuted ?? 0,
  relevanceRejectedCount: sum('relevanceRejectedCount'),
  searchFailedQueries: search.stats?.failedQueries ?? (search.error ? 1 : 0),
  areaRejectedCount: search.stats?.areaRejectedCount ?? 0,
  blockedDomainCount: search.stats?.blockedDomainCount ?? 0,
  duplicateCandidateCount: search.stats?.duplicateCount ?? 0,
  rawCandidateCount: search.stats?.rawCandidateCount ?? 0,
  uniquePlaceCount: search.stats?.uniquePlaceCount ?? 0,
  noWebsiteCount: search.stats?.noWebsiteCount ?? 0,
  paginationRepeatCount: search.stats?.paginationRepeatCount ?? 0,
  exhaustedQueryCount: search.stats?.exhaustedQueryCount ?? 0,
  pageCapReachedQueryCount: search.stats?.pageCapReachedQueryCount ?? 0,
  maxPages: search.stats?.maxPages ?? 1,
  hpFetchFailureCount: sum('errorCount'),
  placesCandidateCount: search.stats?.placesCandidateCount ?? 0,
  organicCandidateCount: search.stats?.organicCandidateCount ?? 0,
  organicRawCandidateCount: search.stats?.organicRawCandidateCount ?? 0,
  organicRejectedCount: search.stats?.organicRejectedCount ?? 0,
  organicQueriesExecuted: search.stats?.organicQueriesExecuted ?? 0,
  organicFailedQueries: search.stats?.organicFailedQueries ?? 0,
  organicExhaustedQueryCount: search.stats?.organicExhaustedQueryCount ?? 0,
  organicPageCapReachedQueryCount: search.stats?.organicPageCapReachedQueryCount ?? 0,
  organicMaxPages: search.stats?.organicMaxPages ?? 0,
  searchTimeBudgetReached: search.stats?.searchTimeBudgetReached ?? false,
  searchElapsedMs: search.stats?.searchElapsedMs ?? 0,
  relevanceReasonCounts,
  relevanceAcceptedCount: sum('relevanceAcceptedCount'),
  relevanceHoldCount: sum('relevanceHoldCount'),
  portalQueriesExecuted: search.portalStats?.portalQueriesExecuted ?? 0,
  portalFailedQueries: search.portalStats?.portalFailedQueries ?? 0,
  portalDiscoveryOrganicResults: search.portalStats?.discoveryOrganicResults ?? 0,
  portalListingPagesFound: search.portalStats?.listingPagesFound ?? 0,
  portalListingPagesFetched: search.portalStats?.listingPagesFetched ?? 0,
  portalDetailPagesFetched: search.portalStats?.detailPagesFetched ?? 0,
  portalBusinessesExtracted: search.portalStats?.businessesExtracted ?? 0,
  portalDedupedBusinessCount: search.portalStats?.dedupedBusinessCount ?? 0,
  portalOfficialLinkCount: search.portalStats?.officialLinkFromPortal ?? 0,
  portalOfficialFoundByResearch: search.portalStats?.officialFoundByResearch ?? 0,
  portalResearchQueriesExecuted: search.portalStats?.researchQueriesExecuted ?? 0,
  portalFetchFailedCount: search.portalStats?.fetchFailedCount ?? 0,
  portalDeadlineReached: search.portalStats?.deadlineReached ?? false,
  hpNotFoundCount: search.hpNotFoundCount ?? 0,
  hpNotFoundSaved: search.hpNotFoundSaved ?? 0,
  expectedCandidateCount,
  processedCandidateCount,
  pendingCandidateCount,
  batchCount,
  completedBatchCount,
  failedBatchCount,
  resultSetComplete,
  warnings: [...new Set(warningMessages)],
};
return [{
  json: {
    status: error || !resultSetComplete ? 'error' : 'success',
    error: error || undefined,
    runId: p.runId || '',
    results,
  },
  pairedItem: { item: 0 },
}];
